import math

import pytest

from estimate import (average_qps, bandwidth_gbit, downtime_minutes_per_year, in_flight, peak_qps, percentile,
                      serial_availability, storage_tb)


def test_average_qps():
    assert average_qps(86_400) == pytest.approx(1)
    assert average_qps(1_000_000) == pytest.approx(11.574, rel=1e-3)


def test_peak_qps():
    assert peak_qps(100, 3) == pytest.approx(300)


def test_storage_tb():
    # one million 1 MB objects a day for a year, stored three times
    assert storage_tb(1_000_000, 1_000_000, 365, 3) == pytest.approx(1095)


def test_bandwidth_gbit():
    assert bandwidth_gbit(1_000, 500_000) == pytest.approx(4.0)


def test_downtime():
    assert downtime_minutes_per_year(0.999) == pytest.approx(525.6)
    assert downtime_minutes_per_year(0.9999) == pytest.approx(52.56)


def test_serial_availability():
    assert serial_availability(0.999, 0.999) == pytest.approx(0.998001)


def test_littles_law():
    assert in_flight(2_000, 0.050) == pytest.approx(100)


def test_percentile_nearest_rank():
    samples = list(range(1, 101))          # 1..100
    assert percentile(samples, 50) == 50
    assert percentile(samples, 99) == 99
    assert percentile([5, 1, 3], 100) == 5
    assert math.isclose(percentile([7.5], 1), 7.5)

"""Rate limiters: a token bucket to build, and a fixed-window counter to compare it with.

Both take a `clock`: a function returning seconds. Real code uses time.monotonic, which never
jumps backwards when the system clock is corrected; the tests pass a fake clock instead.
"""
from __future__ import annotations

import math
import time
from typing import Callable

Clock = Callable[[], float]


class TokenBucket:
    """Allows bursts of up to `capacity` requests and `rate` requests a second on average.

    The bucket starts full. Tokens are added continuously, `rate` per second, but never beyond
    `capacity`. A request costs `cost` tokens and is allowed only if that many are there.
    """

    def __init__(self, capacity: float, rate: float, clock: Clock = time.monotonic):
        if capacity <= 0 or rate <= 0:
            raise ValueError("capacity and rate must be positive")
        self.capacity = capacity
        self.rate = rate
        self.clock = clock
        self.tokens = float(capacity)
        self.updated = clock()

    def _refill(self) -> None:
        """Add the tokens earned since the last update, up to capacity."""
        raise NotImplementedError("TODO: elapsed time x rate, capped at capacity; then remember now")

    def allow(self, cost: float = 1) -> bool:
        """Take `cost` tokens and return True, or return False and take nothing."""
        raise NotImplementedError("TODO: refill, then take the tokens if there are enough")

    def retry_after(self, cost: float = 1) -> float:
        """Seconds until `cost` tokens will be available: 0 if they are now."""
        if cost > self.capacity:
            raise ValueError("this request can never be allowed: cost exceeds capacity")
        raise NotImplementedError("TODO: refill, then (missing tokens) / rate, never below 0")


class FixedWindow:
    """At most `limit` requests in each window of `window` seconds, counted from zero again on each new window."""

    def __init__(self, limit: int, window: float, clock: Clock = time.monotonic):
        self.limit, self.window, self.clock = limit, window, clock
        self.current, self.count = None, 0

    def allow(self) -> bool:
        index = math.floor(self.clock() / self.window)
        if index != self.current:
            self.current, self.count = index, 0
        if self.count < self.limit:
            self.count += 1
            return True
        return False


class KeyedLimiter:
    """One token bucket per key (a user, an API key), created the first time the key is seen."""

    def __init__(self, capacity: float, rate: float, clock: Clock = time.monotonic):
