"""An LRU cache with optional per-entry TTLs: a dict for O(1) lookup plus a doubly linked list for recency.

The list runs from the most recently used entry (just after `head`) to the least recently used
(just before `tail`). `head` and `tail` are sentinels, so no operation needs to check for None.
"""
from __future__ import annotations

import time
from typing import Any, Callable, Hashable


class _Node:
    __slots__ = ("key", "value", "expires", "prev", "next")

    def __init__(self, key: Hashable = None, value: Any = None, expires: float | None = None):
        self.key, self.value, self.expires = key, value, expires
        self.prev: _Node | None = None
        self.next: _Node | None = None


class LRUCache:
    def __init__(self, capacity: int, clock: Callable[[], float] = time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.clock = clock
        self.map: dict[Hashable, _Node] = {}
        self.head, self.tail = _Node(), _Node()
        self.head.next, self.tail.prev = self.tail, self.head
        self.hits = self.misses = self.evictions = 0

    # The two list operations everything else is built from.
    def _unlink(self, node: _Node) -> None:
        node.prev.next, node.next.prev = node.next, node.prev

    def _push_front(self, node: _Node) -> None:
        node.prev, node.next = self.head, self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key: Hashable, default: Any = None) -> Any:
        """Return the value and mark it most recently used; count a hit or a miss.
        An expired entry is removed and counts as a miss."""
        raise NotImplementedError("TODO")

    def put(self, key: Hashable, value: Any, ttl: float | None = None) -> None:
        """Insert or replace an entry as the most recently used; if that makes the cache too big,
        evict the least recently used entry. `ttl` is in seconds; None means no expiry."""
        raise NotImplementedError("TODO")

    def delete(self, key: Hashable) -> bool:
        """Remove an entry; return whether it was there. Deleting twice is harmless."""
        raise NotImplementedError("TODO")

    def keys(self) -> list[Hashable]:
        """Keys from most to least recently used."""
        out, node = [], self.head.next
        while node is not self.tail:
            out.append(node.key)
            node = node.next
        return out

    def __len__(self) -> int:
        return len(self.map)

    @property
    def hit_ratio(self) -> float:
        total = self.hits + self.misses
        return self.hits / total if total else 0.0

