"""A consistent-hash ring with virtual nodes, and plain modulo hashing to compare it with."""
from __future__ import annotations

import bisect
import hashlib


def stable_hash(text: str) -> int:
    """A 64-bit hash that is the same in every process and on every machine.
    (Python's built-in hash() of a str changes between runs, so it can't place data.)"""
    return int.from_bytes(hashlib.md5(text.encode("utf-8")).digest()[:8], "big")


def modulo_node(key: str, nodes: list[str]) -> str:
    return nodes[stable_hash(key) % len(nodes)]


class HashRing:
    """Each node owns `vnodes` points on a ring of 2**64 positions. A key belongs to the node that
    owns the first point at or after the key's own position, wrapping round past the top."""

    def __init__(self, nodes: tuple[str, ...] | list[str] = (), vnodes: int = 100):
        self.vnodes = vnodes
        self._points: list[int] = []        # sorted positions
        self._owner: dict[int, str] = {}    # position -> node
        for node in nodes:
            self.add(node)

    def add(self, node: str) -> None:
        """Give the node `vnodes` points, at stable_hash(f"{node}#{i}") for i in range(vnodes)."""
