import pytest

import base62
from ring import HashRing, modulo_node, stable_hash



@pytest.fixture(scope="module")
def keys():
    return [base62.encode(1_000_000 + i) for i in range(10_000)]


def test_base62_known_values():
    assert [base62.encode(n) for n in (0, 9, 10, 61, 62, 3843, 3844)] == ["0", "9", "a", "Z", "10", "ZZ", "100"]


def test_base62_round_trip():
    for n in (0, 1, 61, 62, 12_345_678_901, 62 ** 7 - 1):
        assert base62.decode(base62.encode(n)) == n
    assert len(base62.encode(62 ** 7 - 1)) == 7


def test_stable_hash_is_stable():
    assert stable_hash("abc") == 10376663631224000432


def test_empty_ring():
    with pytest.raises(LookupError):
        HashRing().node_for("x")


def test_every_key_finds_a_node_and_the_answer_never_changes(keys):
    ring = HashRing(["db-a", "db-b", "db-c"])
    first = [ring.node_for(k) for k in keys]
    assert set(first) == {"db-a", "db-b", "db-c"}
    other = HashRing(["db-c", "db-a", "db-b"])               # the order nodes are added in doesn't matter
    assert first == [other.node_for(k) for k in keys]


def test_adding_a_node_only_moves_keys_to_it(keys):
    ring = HashRing(["db-a", "db-b", "db-c", "db-d"])
    before = {k: ring.node_for(k) for k in keys}
    ring.add("db-e")
    moved = {k: ring.node_for(k) for k in keys if ring.node_for(k) != before[k]}
    assert set(moved.values()) == {"db-e"}
    assert 0.12 < len(moved) / len(keys) < 0.28          # about 1/5


def test_removing_a_node_only_moves_its_keys(keys):
    ring = HashRing(["db-a", "db-b", "db-c", "db-d"])
    before = {k: ring.node_for(k) for k in keys}
    ring.remove("db-b")
    for k in keys:
        if before[k] != "db-b":
            assert ring.node_for(k) == before[k]
    assert "db-b" not in ring.nodes()


def test_modulo_moves_most_keys(keys):
    four = ["db-a", "db-b", "db-c", "db-d"]
    moved = sum(modulo_node(k, four) != modulo_node(k, four + ["db-e"]) for k in keys)
    assert moved / len(keys) > 0.7


def test_virtual_nodes_balance_the_load(keys):
    ring = HashRing([f"db-{i}" for i in range(5)], vnodes=1000)
    counts = Counter(ring.node_for(k) for k in keys)
    assert max(counts.values()) / (len(keys) / 5) < 1.15

"""A tiny payment service on SQLite: a naive charge, and a charge that is safe to retry."""
