import sqlite3

SCHEMA = """
CREATE TABLE IF NOT EXISTS accounts (
    id TEXT PRIMARY KEY,
    balance_pence INTEGER NOT NULL CHECK (balance_pence >= 0)
);
CREATE TABLE IF NOT EXISTS charges (
    id INTEGER PRIMARY KEY,
    account_id TEXT NOT NULL REFERENCES accounts(id),
    amount_pence INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS idempotency_keys (
    key TEXT PRIMARY KEY,               -- the UNIQUE guard: a key can be stored once
    request_hash TEXT NOT NULL,         -- what the key was first used for
    response TEXT NOT NULL              -- the JSON response to replay
);
CREATE TABLE IF NOT EXISTS processed_messages (
    message_id TEXT PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS loyalty_points (
    account_id TEXT PRIMARY KEY,
    points INTEGER NOT NULL
);
"""


def connect(path: str = ":memory:") -> sqlite3.Connection:
    conn = sqlite3.connect(path, isolation_level=None)     # autocommit: we write BEGIN and COMMIT ourselves
    conn.executescript(SCHEMA)
    return conn


def open_account(conn: sqlite3.Connection, account_id: str, balance_pence: int) -> None:
    conn.execute("INSERT INTO accounts (id, balance_pence) VALUES (?, ?)", (account_id, balance_pence))


def balance(conn: sqlite3.Connection, account_id: str) -> int:
    return conn.execute("SELECT balance_pence FROM accounts WHERE id = ?", (account_id,)).fetchone()[0]


def charge_count(conn: sqlite3.Connection) -> int:
    return conn.execute("SELECT count(*) FROM charges").fetchone()[0]


def _apply_charge(conn: sqlite3.Connection, account_id: str, amount_pence: int) -> dict:
    """Inside an open transaction: take the money and record the charge, or decline."""
    if balance(conn, account_id) < amount_pence:
        return {"status": "declined", "reason": "insufficient funds"}
    conn.execute("UPDATE accounts SET balance_pence = balance_pence - ? WHERE id = ?", (amount_pence, account_id))
    cur = conn.execute("INSERT INTO charges (account_id, amount_pence) VALUES (?, ?)", (account_id, amount_pence))
    return {"status": "charged", "charge_id": cur.lastrowid, "amount_pence": amount_pence}


def naive_charge(conn: sqlite3.Connection, account_id: str, amount_pence: int) -> dict:
    """Every call takes the money, including a client's retry of a request that had already succeeded."""
    conn.execute("BEGIN IMMEDIATE")
    try:
        response = _apply_charge(conn, account_id, amount_pence)
        conn.execute("COMMIT")
        return response
    except BaseException:
        conn.execute("ROLLBACK")
        raise


def request_hash(account_id: str, amount_pence: int) -> str:
    return hashlib.sha256(f"{account_id}|{amount_pence}".encode()).hexdigest()


